class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        url = urlparse(self.path)
        if url.path == "/api/chunk-job":
            job_id = parse_qs(url.query).get("id", [""])[0]
            job = get_analysis_job(job_id)
            if job is None:
                self.respond(404, json.dumps({"error": "Phiên xử lý không còn. Hãy phân tích lại file."}, ensure_ascii=False).encode(), "application/json; charset=utf-8")
            else:
                self.respond(200, json.dumps(job, ensure_ascii=False).encode(), "application/json; charset=utf-8")
            return
        if self.path == "/api/llm-status":
            ready = has_api_key()
            self.respond(200, json.dumps({"ready": ready, "model": MODEL}).encode(), "application/json; charset=utf-8")
            return
        if self.path == "/api/library":
            self.respond(200, json.dumps({"files": list_files()}, ensure_ascii=False).encode(), "application/json; charset=utf-8")
            return
        if self.path != "/":
            self.send_error(404)
            return
        self.respond(200, PAGE.encode(), "text/html; charset=utf-8")

    def do_POST(self):
        url = urlparse(self.path)
        if url.path == "/api/chunk-job":
            try:
                params = parse_qs(url.query)
                filename = Path(params.get("filename", [""])[0]).name
                semantic = params.get("semantic", ["false"])[0].lower() == "true"
                threshold = float(params.get("threshold", ["0.85"])[0])
                size = int(self.headers.get("Content-Length", "0"))
                if Path(filename).suffix.lower() not in (".pdf", ".docx"):
                    raise ValueError("Chỉ hỗ trợ PDF và DOCX")
                if size <= 0 or size > MAX_UPLOAD:
                    raise ValueError("File rỗng hoặc vượt quá 30 MB")
                if not 0.5 <= threshold <= 0.95:
                    raise ValueError("Ngưỡng ngữ nghĩa phải nằm trong khoảng 0.50–0.95")
                job_id = submit_analysis_job(filename, self.rfile.read(size), semantic, threshold)
                self.respond(202, json.dumps({"id": job_id}).encode(), "application/json; charset=utf-8")
            except RuntimeError as exc:
                self.respond(503, json.dumps({"error": str(exc)}, ensure_ascii=False).encode(), "application/json; charset=utf-8")
            except Exception as exc:
                self.respond(400, json.dumps({"error": str(exc)}, ensure_ascii=False).encode(), "application/json; charset=utf-8")
            return
        if url.path == "/api/library":
            try:
                size = int(self.headers.get("Content-Length", "0"))
                if size <= 0 or size > MAX_UPLOAD:
                    raise ValueError("File rỗng hoặc vượt quá 30 MB")
                filename = Path(parse_qs(url.query).get("filename", [""])[0]).name
                body = self.rfile.read(size)
                with tempfile.TemporaryDirectory() as folder:
                    path = Path(folder) / filename
                    path.write_bytes(body)
                    description = describe_file(path)
                saved = add_file(filename, body, description)
                self.respond(200, json.dumps({"file": saved}, ensure_ascii=False).encode(), "application/json; charset=utf-8")
            except Exception as exc:
                self.respond(400, json.dumps({"error": str(exc)}, ensure_ascii=False).encode(), "application/json; charset=utf-8")
            return
        if url.path == "/api/library-description":
            try:
                size = int(self.headers.get("Content-Length", "0"))
                if size <= 0 or size > 8192:
                    raise ValueError("Mô tả không hợp lệ")
                payload = json.loads(self.rfile.read(size))
                if not update_description(payload["id"], payload["description_md"]):
                    raise ValueError("Không tìm thấy file trong thư viện")
                self.respond(200, b'{"ok":true}', "application/json; charset=utf-8")
            except Exception as exc:
                self.respond(400, json.dumps({"error": str(exc)}, ensure_ascii=False).encode(), "application/json; charset=utf-8")
            return
        if url.path == "/api/llm-match-tag":
            try:
                size = int(self.headers.get("Content-Length", "0"))
                if size <= 0 or size > MAX_UPLOAD:
                    raise ValueError("Dữ liệu tag không hợp lệ")
                payload = json.loads(self.rfile.read(size))
                result = match_one_tag(payload["chunks"])
                self.respond(200, json.dumps(result, ensure_ascii=False).encode(), "application/json; charset=utf-8")
            except Exception as exc:
                self.respond(400, json.dumps({"error": str(exc)}, ensure_ascii=False).encode(), "application/json; charset=utf-8")
            return
        if url.path == "/api/bid-report":
            try:
                size = int(self.headers.get("Content-Length", "0"))
                if size <= 0 or size > MAX_UPLOAD:
                    raise ValueError("Dữ liệu bản tổng hợp không hợp lệ")
                payload = json.loads(self.rfile.read(size))
                if not isinstance(payload.get("documents"), list) or not isinstance(payload.get("matches"), list):
                    raise ValueError("Thiếu tài liệu hoặc kết quả gợi ý file")
                result = generate_report(payload["documents"], payload["matches"])
                self.respond(200, json.dumps(result, ensure_ascii=False).encode(), "application/json; charset=utf-8")
            except Exception as exc:
                self.respond(400, json.dumps({"error": str(exc)}, ensure_ascii=False).encode(), "application/json; charset=utf-8")
            return
        if url.path != "/api/chunk":

            self.send_error(404)
            return
        filename = Path(parse_qs(url.query).get("filename", [""])[0]).name
        suffix = Path(filename).suffix.lower()
        try:
            params = parse_qs(url.query)
            semantic = params.get("semantic", ["false"])[0].lower() == "true"
            threshold = float(params.get("threshold", ["0.85"])[0])
            size = int(self.headers.get("Content-Length", "0"))
            if suffix not in (".pdf", ".docx"):
                raise ValueError("Chỉ hỗ trợ PDF và DOCX")
            if size <= 0 or size > MAX_UPLOAD:
                raise ValueError("File rỗng hoặc vượt quá 30 MB")
            body = self.rfile.read(size)
            with tempfile.TemporaryDirectory() as folder:
                path = Path(folder) / filename
                path.write_bytes(body)
                result = chunk_file(path, semantic=semantic, threshold=threshold)
            self.respond(200, json.dumps(result, ensure_ascii=False).encode(), "application/json; charset=utf-8")
        except Exception as exc:
            self.respond(400, json.dumps({"error": str(exc)}, ensure_ascii=False).encode(), "application/json; charset=utf-8")

    def respond(self, code: int, data: bytes, mime: str) -> None:
        self.send_response(code)
        self.send_header("Content-Type", mime)
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)


if __name__ == "__main__":
    railway_port = os.environ.get("PORT")
    port = int(railway_port or os.environ.get("STRUCTURAL_CHUNKER_PORT", "8765"))
    host = "0.0.0.0" if railway_port else "127.0.0.1"
    server = ThreadingHTTPServer((host, port), Handler)
    print(f"Listening on {host}:{port} (Ctrl+C to stop)", flush=True)
    server.serve_forever()
